def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(v == c for row in grid for v in row) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])
    out = [row[:] for row in grid]

    # Find contiguous, non-background runs of length at least two on each edge.
    def runs(cells):
        result = []
        i = 0
        while i < len(cells):
            r, c = cells[i]
            color = grid[r][c]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(cells) and grid[cells[j][0]][cells[j][1]] == color:
                j += 1
            if j - i >= 2:
                result.append((color, cells[i:j]))
            i = j
        return result

    top = runs([(0, c) for c in range(w)])
    bottom = runs([(h - 1, c) for c in range(w)])
    left = runs([(r, 0) for r in range(h)])
    right = runs([(r, w - 1) for r in range(h)])

    bars = set()
    for edge_runs in (top, bottom, left, right):
        for _, cells in edge_runs:
            bars.update(cells)

    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bars]
    if not markers:
        return out

    marker_counts = {}
    for _, _, color in markers:
        marker_counts[color] = marker_counts.get(color, 0) + 1
    ray_color = max(marker_counts, key=marker_counts.get)

    def cast_pair(run_a, run_b, horizontal):
        color, cells_a = run_a
        color_b, cells_b = run_b
        if color != color_b:
            return
        start_a = cells_a[0][1] if horizontal else cells_a[0][0]
        start_b = cells_b[0][1] if horizontal else cells_b[0][0]
        len_a, len_b = len(cells_a), len(cells_b)
        active = set()

        # A marker aligned with either bar activates the corresponding offset
        # on both opposing bars.
        for r, c, _ in markers:
            pos = c if horizontal else r
            if start_a <= pos < start_a + len_a:
                active.add(pos - start_a)
            if start_b <= pos < start_b + len_b:
                active.add(pos - start_b)

        for offset in active:
            if offset >= len_a or offset >= len_b:
                continue
            if horizontal:
                ca, cb = start_a + offset, start_b + offset
                sources = [(0, ca, 1, 0), (h - 1, cb, -1, 0)]
            else:
                ra, rb = start_a + offset, start_b + offset
                sources = [(ra, 0, 0, 1), (rb, w - 1, 0, -1)]

            for r, c, dr, dc in sources:
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != bg:
                        out[rr][cc] = 4
                        break
                    out[rr][cc] = ray_color
                    rr += dr
                    cc += dc

    # Pair corresponding same-colored runs on opposite edges, in order.
    for a, b in zip(top, bottom):
        cast_pair(a, b, True)
    for a, b in zip(left, right):
        cast_pair(a, b, False)

    return out

